sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float progress;
uniform float angle;
uniform float feather;
uniform float mode;
layout(color) uniform half4 glowColor;
uniform float glowWidth;
uniform float glowAmount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 dir = float2(cos(radians(angle)), sin(radians(angle)));
    float len = abs(size.x * dir.x) + abs(size.y * dir.y);
    float t = dot(coord - size * 0.5, dir) + len * 0.5;
    float f = max(feather, 0.5);
    float edgePos = progress * (len + f) - f;
    float reveal = 1.0 - smoothstep(edgePos, edgePos + f, t);
    float mask = mode < 0.5 ? reveal : 1.0 - reveal;
    float glow = exp(-pow((t - (edgePos + f * 0.5)) / max(glowWidth, 1.0), 2.0)) * glowAmount;
    float3 o = s * mask + float3(glowColor.rgb) * glow;
    float4 r = float4(max(o, float3(0.0)) * c.a, c.a * mask);
    return fin(c, r, opacity);
}
